INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('134', '21', '4', '4', 'calculation', '14', '计算
\[I=\int_0^{2\pi}d\varphi\int_0^\pi e^{\sin\theta(\cos\varphi-\sin\varphi)}\sin\theta\,d\theta.\]', '\(\displaystyle I=\sqrt2\pi(e^{\sqrt2}-e^{-\sqrt2})\)。', '把积分视为单位球面上 \(e^{x-y}\) 的面积分，旋转坐标轴使新极轴沿 \((1,-1,0)\)，化为 \(2\pi\int_0^\pi e^{\sqrt2\cos\alpha}\sin\alpha,d\alpha\)。', '2019 年第十一届全国大学生数学竞赛初赛（非数学类） 计算 [I= 0 2 d 0 e ( - ) ,d . ] ( I= 2 (e 2 -e - 2 ) )。 把积分视为单位球面上 (e x-y ) 的面积分，旋转坐标轴使新极轴沿 ((1,-1,0) )，化为 (2 0 e 2 ,d )。', '1', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('135', '21', '5', '5', 'proof', '14', '设多项式 \(f(x)\) 的根全为正实数，并在原点附近展开
\[-\frac{f''(x)}{f(x)}=\sum_{n=0}^\infty c_nx^n.\]
证明 \(c_n>0\)，且 \(\displaystyle\lim_{n\to\infty}c_n^{-1/n}\) 等于 \(f\) 的最小正根。', '各 \(c_n>0\)，所给极限等于最小正根。', '若各根为 \(r_j>0\)，则 \(-f''/f=\sum_j1/(r_j-x)=\sum_{n\ge0}(\sum_jr_j^{-n-1})x^n\)。因此系数为正；最大项由最小根控制，取 \(n\) 次根即得结论。', '2019 年第十一届全国大学生数学竞赛初赛（非数学类） 设多项式 (f(x) ) 的根全为正实数，并在原点附近展开 [- f''(x) f(x) = n=0 c nx n. ] 证明 (c n>0 )，且 ( n c n -1/n ) 等于 (f ) 的最小正根。 各 (c n>0 )，所给极限等于最小正根。 若各根为 (r j>0 )，则 (-f''/f= j1/(r j-x)= n 0 ( jr j -n-1 )x n )。因此系数为正；最大项由最小根控制，取 (n ) 次根即得结论。', '1', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('136', '21', '6', '6', 'proof', '14', '函数 \(f\) 满足
\[3[3+f^2(x)]f''(x)=2[1+f^2(x)]^2e^{-x^2},\qquad f(0)\le1.\]
证明 \(f\) 在实轴上有界。', '\(f\) 在 \(\mathbb R\) 上有界。', '分离变量并注意 \(\frac{3(3+u^2)}{2(1+u^2)^2}\) 在无穷远可积，而右端 \(e^{-x^2}\) 的总积分有限。结合初值上界比较可知解不能在有限或无限区间逃向无穷。', '2019 年第十一届全国大学生数学竞赛初赛（非数学类） 函数 (f ) 满足 [3[3+f 2(x)]f''(x)=2[1+f 2(x)] 2e -x 2 , f(0) 1. ] 证明 (f ) 在实轴上有界。 (f ) 在 ( R ) 上有界。 分离变量并注意 ( 3(3+u 2) 2(1+u 2) 2 ) 在无穷远可积，而右端 (e -x 2 ) 的总积分有限。结合初值上界比较可知解不能在有限或无限区间逃向无穷。', '1', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('137', '22', '1', '1', 'calculation', '30', '填空题，共 5 小题，每小题 6 分。

1. 求 \(\displaystyle\lim_{x\to\pi/2}\frac{(1-\sqrt{\sin x})(1-\sqrt[3]{\sin x})\cdots(1-\sqrt[n]{\sin x})}{(1-\sin x)^{n-1}}\)。
2. 曲线 \(3x-y=2\arctan(y-2x)\)，求其在 \(P(1+\pi/2,3+\pi)\) 处切线。
3. 二次曲线通过 \((-1,0),(0,-1),(0,1),(2,-1),(2,1)\)，求曲线上两点最大距离。
4. \(f(x)=(x^2+2x-3)^n\arctan^2(x/3)\)，求 \(f^{(n)}(-3)\)。
5. \(f(0)=f(1)=0\)，且 \(\int_0^1[f''(x)]^2dx-8\int_0^1f(x)dx+4/3=0\)，求 \(f\)。', '1. \(1/n!\)。 2. \(\displaystyle y=\frac52x+\frac12-\frac\pi4\)。 3. \(4\)。
4. \(\displaystyle(-1)^n4^{n-2}n!\pi^2\)。 5. \(f(x)=2x-2x^2\)。', '1. 每个因子除以 \(1-\sin x\) 后取极限。 2. 隐式求导。
3. 代入五点得椭圆 \((x-1)^2/4+y^2/(4/3)=1\)。 4. 提取 \((x+3)^n\) 后用 Leibniz 公式。
5. 分部积分把题设化为 \(\int_0^1[f''(x)+4x-2]^2dx=0\)。', '2021 年第十一届全国大学生数学竞赛决赛（非数学类） 填空题，共 5 小题，每小题 6 分。 1. 求 ( x /2 (1- x )(1- [3] x ) (1- [n] x ) (1- x) n-1 )。 2. 曲线 (3x-y=2 (y-2x) )，求其在 (P(1+ /2,3+ ) ) 处切线。 3. 二次曲线通过 ((-1,0),(0,-1),(0,1),(2,-1),(2,1) )，求曲线上两点最大距离。 4. (f(x)=(x 2+2x-3) n 2(x/3) )，求 (f (n) (-3) )。 5. (f(0)=f(1)=0 )，且 ( 0 1[f''(x)] 2dx-8 0 1f(x)dx+4/3=0 )，求 (f )。 1. (1/n! )。 2. ( y= 52x+ 12- 4 )。 3. (4 )。 4. ( (-1) n4 n-2 n! 2 )。 5. (f(x)=2x-2x 2 )。 1. 每个因子除以 (1- x ) 后取极限。 2. 隐式求导。 3. 代入五点得椭圆 ((x-1) 2/4+y 2/(4/3)=1 )。 4. 提取 ((x+3) n ) 后用 Leibniz 公式。 5. 分部积分把题设化为 ( 0 1[f''(x)+4x-2] 2dx=0 )。', '1', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('138', '22', '2', '2', 'calculation', '12', '求极限
\[\lim_{n\to\infty}n\left(1-\sum_{k=1}^n\frac1{\sqrt{n+k}}\right).\]', '\(\displaystyle\frac23\)。', '把差写成 \(\sum_{k=1}^n(1/\sqrt n-1/\sqrt{n+k})\)，有理化后用积分上下和夹逼，极限为 \(2/3\)。', '2021 年第十一届全国大学生数学竞赛决赛（非数学类） 求极限 [ n n (1- k=1 n 1 n+k ). ] ( 23 )。 把差写成 ( k=1 n(1/ n-1/ n+k ) )，有理化后用积分上下和夹逼，极限为 (2/3 )。', '1', 'published') ON CONFLICT (id) DO NOTHING;